-- AIEO Phase 1 M1 initial schema.
-- Contract: docs/phase1/platform-contract-v1.0.md C2 (16 core tables).
-- Internal support tables (not part of the frozen 16): task_events,
-- platform_users, user_sessions, service_credentials.
-- All timestamps are TEXT ISO 8601 UTC generated by the application layer.
-- Forward-only migration; no module may alter tables outside migrations.

-- 1. projects
CREATE TABLE projects (
    project_id        TEXT PRIMARY KEY,
    name              TEXT NOT NULL UNIQUE,
    description       TEXT,
    status            TEXT NOT NULL DEFAULT 'ACTIVE' CHECK(status IN ('ACTIVE','ARCHIVED')),
    knowledge_version TEXT,
    created_at        TEXT NOT NULL,
    updated_at        TEXT NOT NULL
);

-- 2. agents
CREATE TABLE agents (
    agent_id     TEXT PRIMARY KEY,
    agent_type   TEXT NOT NULL CHECK(agent_type IN ('system','developer','reviewer','tester','auditor','user')),
    role         TEXT NOT NULL,
    enabled      INTEGER NOT NULL DEFAULT 1 CHECK(enabled IN (0,1)),
    capabilities TEXT,
    created_at   TEXT NOT NULL,
    updated_at   TEXT NOT NULL
);

-- 3. repositories
CREATE TABLE repositories (
    repository_id  TEXT PRIMARY KEY,
    project_id     TEXT NOT NULL REFERENCES projects(project_id),
    url            TEXT NOT NULL,
    local_path     TEXT NOT NULL UNIQUE,
    default_branch TEXT NOT NULL DEFAULT 'main',
    created_at     TEXT NOT NULL,
    updated_at     TEXT NOT NULL
);
CREATE INDEX idx_repositories_project ON repositories(project_id);

-- 4. batches
CREATE TABLE batches (
    batch_id                     TEXT PRIMARY KEY,
    project_id                   TEXT NOT NULL REFERENCES projects(project_id),
    requirement                  TEXT NOT NULL,
    status                       TEXT NOT NULL DEFAULT 'PLANNING' CHECK(status IN ('PLANNING','PLANNED','EXECUTING','COMPLETED','CANCELLED')),
    engineering_standard_version TEXT NOT NULL,
    knowledge_base_commit        TEXT NOT NULL,
    created_at                   TEXT NOT NULL,
    updated_at                   TEXT NOT NULL
);
CREATE INDEX idx_batches_project ON batches(project_id);
CREATE INDEX idx_batches_status ON batches(status);

-- 5. tasks
CREATE TABLE tasks (
    task_id                     TEXT PRIMARY KEY,
    batch_id                    TEXT NOT NULL REFERENCES batches(batch_id),
    parent_id                   TEXT REFERENCES tasks(task_id),
    title                       TEXT NOT NULL,
    description                 TEXT,
    status                      TEXT NOT NULL DEFAULT 'DRAFT' CHECK(status IN ('DRAFT','PLANNING','ARCH_REVIEW','READY','DISPATCHED','IN_PROGRESS','DEV_REPORTED','GIT_VALIDATING','CODE_REVIEW','TEST_ACCEPTANCE','REWORK','BLOCKED','ACCEPTED','CANCELLED')),
    priority                    TEXT NOT NULL DEFAULT 'P2' CHECK(priority IN ('P0','P1','P2','P3')),
    weight                      REAL NOT NULL DEFAULT 1.0 CHECK(weight > 0),
    files_scope                 TEXT NOT NULL,
    acceptance_criteria         TEXT NOT NULL,
    engineering_standard_items  TEXT NOT NULL,
    task_package_hash           TEXT NOT NULL,
    engineering_standard_version TEXT NOT NULL,
    knowledge_base_commit       TEXT NOT NULL,
    blocked_reason              TEXT,
    blocked_owner               TEXT,
    unblock_condition           TEXT,
    cancelled_by                TEXT,
    cancelled_reason            TEXT,
    created_at                  TEXT NOT NULL,
    updated_at                  TEXT NOT NULL,
    CHECK(status != 'BLOCKED' OR (blocked_reason IS NOT NULL AND blocked_owner IS NOT NULL AND unblock_condition IS NOT NULL)),
    CHECK(status != 'CANCELLED' OR (cancelled_by IS NOT NULL AND cancelled_reason IS NOT NULL))
);
CREATE INDEX idx_tasks_batch ON tasks(batch_id);
CREATE INDEX idx_tasks_status ON tasks(status);
CREATE INDEX idx_tasks_parent ON tasks(parent_id);

-- 6. task_dependencies
CREATE TABLE task_dependencies (
    task_id            TEXT NOT NULL REFERENCES tasks(task_id),
    depends_on_task_id TEXT NOT NULL REFERENCES tasks(task_id),
    PRIMARY KEY (task_id, depends_on_task_id),
    CHECK(task_id != depends_on_task_id)
);
CREATE INDEX idx_task_dependencies_dep ON task_dependencies(depends_on_task_id);

-- 7. task_executions
CREATE TABLE task_executions (
    execution_id TEXT PRIMARY KEY,
    task_id      TEXT NOT NULL REFERENCES tasks(task_id),
    agent_id     TEXT NOT NULL REFERENCES agents(agent_id),
    attempt      INTEGER NOT NULL CHECK(attempt >= 1),
    base_commit  TEXT NOT NULL CHECK(length(base_commit) = 40),
    status       TEXT NOT NULL DEFAULT 'RUNNING' CHECK(status IN ('RUNNING','COMPLETED','FAILED','CANCELLED')),
    started_at   TEXT NOT NULL,
    ended_at     TEXT,
    created_at   TEXT NOT NULL,
    UNIQUE(task_id, attempt)
);
CREATE INDEX idx_task_executions_task ON task_executions(task_id);

-- 8. agent_sessions
CREATE TABLE agent_sessions (
    session_id   TEXT PRIMARY KEY,
    agent_id     TEXT NOT NULL REFERENCES agents(agent_id),
    session_url  TEXT,
    profile_key  TEXT,
    status       TEXT NOT NULL DEFAULT 'ACTIVE' CHECK(status IN ('ACTIVE','SUSPENDED','OFFLINE','EXPIRED')),
    last_seen_at TEXT,
    created_at   TEXT NOT NULL,
    updated_at   TEXT NOT NULL
);
CREATE INDEX idx_agent_sessions_agent ON agent_sessions(agent_id);

-- 9. messages (Inbox/Outbox in one table; message_id PK is the dedup key)
CREATE TABLE messages (
    message_id         TEXT PRIMARY KEY,
    schema_version     TEXT NOT NULL,
    message_type       TEXT NOT NULL CHECK(message_type IN ('TASK_PLAN_REQUEST','TASK_PLAN_SUBMITTED','ARCH_REVIEW_REQUEST','ARCH_REVIEW_SUBMITTED','TASK_ASSIGNED','TASK_ACCEPTED','PROGRESS_UPDATED','BLOCKER_REPORTED','DEVELOPMENT_COMPLETED','CODE_REVIEW_REQUEST','CODE_REVIEW_SUBMITTED','TEST_ACCEPTANCE_REQUEST','TEST_ACCEPTANCE_SUBMITTED','AUDIT_REQUEST','AUDIT_SUBMITTED','APPROVAL_REQUIRED')),
    direction          TEXT NOT NULL CHECK(direction IN ('INBOUND','OUTBOUND')),
    source_agent_id    TEXT NOT NULL REFERENCES agents(agent_id),
    target_agent_id    TEXT NOT NULL REFERENCES agents(agent_id),
    project_id         TEXT NOT NULL REFERENCES projects(project_id),
    batch_id           TEXT REFERENCES batches(batch_id),
    task_id            TEXT REFERENCES tasks(task_id),
    correlation_id     TEXT NOT NULL,
    payload            TEXT NOT NULL,
    status             TEXT NOT NULL DEFAULT 'PENDING' CHECK(status IN ('PENDING','SENT','ACKED','RETRYING','DEAD_LETTER','CANCELLED')),
    retry_count        INTEGER NOT NULL DEFAULT 0 CHECK(retry_count >= 0),
    max_retries        INTEGER NOT NULL DEFAULT 8 CHECK(max_retries >= 0),
    next_retry_at      TEXT,
    last_error_code    TEXT,
    last_error_message TEXT,
    delivered_at       TEXT,
    acked_at           TEXT,
    dead_lettered_at   TEXT,
    processing_status  TEXT CHECK(processing_status IN ('PENDING','PROCESSING','PROCESSED','PROCESS_FAILED')),
    processed_at       TEXT,
    created_at         TEXT NOT NULL,
    updated_at         TEXT NOT NULL
);
CREATE INDEX idx_messages_target ON messages(target_agent_id, processing_status);
CREATE INDEX idx_messages_sweep ON messages(direction, status, next_retry_at);
CREATE INDEX idx_messages_correlation ON messages(correlation_id);
CREATE INDEX idx_messages_task ON messages(task_id);
CREATE INDEX idx_messages_project ON messages(project_id);
CREATE INDEX idx_messages_status ON messages(status);

-- 10. artifacts
CREATE TABLE artifacts (
    artifact_id TEXT PRIMARY KEY,
    task_id     TEXT REFERENCES tasks(task_id),
    type        TEXT NOT NULL CHECK(type IN ('TEST_LOG','DEV_REPORT','REVIEW_EVIDENCE','DIFF','ATTACHMENT','OTHER')),
    path        TEXT NOT NULL UNIQUE,
    sha256      TEXT NOT NULL CHECK(length(sha256) = 64),
    created_at  TEXT NOT NULL
);
CREATE INDEX idx_artifacts_task ON artifacts(task_id);

-- 11. git_commits
CREATE TABLE git_commits (
    git_commit_id    INTEGER PRIMARY KEY AUTOINCREMENT,
    task_id          TEXT NOT NULL REFERENCES tasks(task_id),
    execution_id     TEXT NOT NULL REFERENCES task_executions(execution_id),
    repository_id    TEXT NOT NULL REFERENCES repositories(repository_id),
    branch           TEXT NOT NULL,
    sha              TEXT NOT NULL CHECK(length(sha) = 40),
    base_commit      TEXT NOT NULL CHECK(length(base_commit) = 40),
    diff_artifact_id TEXT REFERENCES artifacts(artifact_id),
    created_at       TEXT NOT NULL,
    UNIQUE(repository_id, sha)
);
CREATE INDEX idx_git_commits_task ON git_commits(task_id, execution_id);

-- 12. development_reports
CREATE TABLE development_reports (
    dev_report_id INTEGER PRIMARY KEY AUTOINCREMENT,
    execution_id  TEXT NOT NULL UNIQUE REFERENCES task_executions(execution_id),
    task_id       TEXT NOT NULL REFERENCES tasks(task_id),
    status        TEXT NOT NULL CHECK(status IN ('COMPLETED','BLOCKED')),
    payload       TEXT NOT NULL,
    created_at    TEXT NOT NULL
);
CREATE INDEX idx_dev_reports_task ON development_reports(task_id);

-- 13. review_reports
CREATE TABLE review_reports (
    review_id                   INTEGER PRIMARY KEY AUTOINCREMENT,
    task_id                     TEXT NOT NULL REFERENCES tasks(task_id),
    execution_id                TEXT NOT NULL REFERENCES task_executions(execution_id),
    reviewed_commit             TEXT NOT NULL CHECK(length(reviewed_commit) = 40),
    reviewer_agent_id           TEXT NOT NULL REFERENCES agents(agent_id),
    result                      TEXT NOT NULL CHECK(result IN ('PASS','REWORK','BLOCKED')),
    task_package_hash           TEXT NOT NULL,
    base_commit                 TEXT NOT NULL CHECK(length(base_commit) = 40),
    engineering_standard_version TEXT NOT NULL,
    knowledge_base_commit       TEXT NOT NULL,
    payload                     TEXT NOT NULL,
    created_at                  TEXT NOT NULL,
    UNIQUE(execution_id, reviewed_commit)
);
CREATE INDEX idx_review_reports_task ON review_reports(task_id, execution_id);

-- 14. test_reports
CREATE TABLE test_reports (
    test_report_id   INTEGER PRIMARY KEY AUTOINCREMENT,
    task_id          TEXT NOT NULL REFERENCES tasks(task_id),
    execution_id     TEXT NOT NULL REFERENCES task_executions(execution_id),
    commit_sha       TEXT NOT NULL CHECK(length(commit_sha) = 40),
    execution_result TEXT NOT NULL CHECK(execution_result IN ('EXECUTED_PASS','EXECUTED_FAIL','NOT_EXECUTED','CLAIMED_ONLY','BLOCKED')),
    result           TEXT NOT NULL CHECK(result IN ('PASS','REWORK','BLOCKED')),
    artifact_id      TEXT REFERENCES artifacts(artifact_id),
    payload          TEXT NOT NULL,
    created_at       TEXT NOT NULL,
    UNIQUE(execution_id, commit_sha)
);
CREATE INDEX idx_test_reports_task ON test_reports(task_id, execution_id);

-- 15. approvals
CREATE TABLE approvals (
    approval_id INTEGER PRIMARY KEY AUTOINCREMENT,
    target_type TEXT NOT NULL CHECK(target_type IN ('BATCH_PLAN','ARCH_REVIEW','MERGE_TO_MAIN','RELEASE','DEAD_LETTER_REQUEUE','CONTRACT_CHANGE','OTHER')),
    target_id   TEXT NOT NULL,
    decision    TEXT NOT NULL DEFAULT 'PENDING' CHECK(decision IN ('PENDING','APPROVED','REJECTED')),
    actor       TEXT NOT NULL,
    reason      TEXT,
    decided_at  TEXT,
    created_at  TEXT NOT NULL
);
CREATE INDEX idx_approvals_target ON approvals(target_type, target_id);
CREATE INDEX idx_approvals_decision ON approvals(decision);

-- 16. audit_logs
CREATE TABLE audit_logs (
    audit_id       INTEGER PRIMARY KEY AUTOINCREMENT,
    timestamp      TEXT NOT NULL,
    actor_id       TEXT NOT NULL,
    actor_type     TEXT NOT NULL CHECK(actor_type IN ('user','agent','system')),
    action         TEXT NOT NULL,
    target_type    TEXT NOT NULL,
    target_id      TEXT NOT NULL,
    result         TEXT NOT NULL CHECK(result IN ('SUCCESS','FAILURE','RETRY','BLOCKED','SKIPPED')),
    reason         TEXT,
    correlation_id TEXT,
    details        TEXT
);
CREATE INDEX idx_audit_timestamp ON audit_logs(timestamp);
CREATE INDEX idx_audit_actor ON audit_logs(actor_id);
CREATE INDEX idx_audit_target ON audit_logs(target_type, target_id);
CREATE INDEX idx_audit_correlation ON audit_logs(correlation_id);

-- Internal: task event idempotency (POST /tasks/{id}/events dedup by event_id)
CREATE TABLE task_events (
    event_id       TEXT PRIMARY KEY,
    task_id        TEXT NOT NULL REFERENCES tasks(task_id),
    event          TEXT NOT NULL,
    from_status    TEXT NOT NULL,
    to_status      TEXT NOT NULL,
    actor_id       TEXT NOT NULL,
    correlation_id TEXT,
    response       TEXT NOT NULL,
    created_at     TEXT NOT NULL
);
CREATE INDEX idx_task_events_task ON task_events(task_id);

-- Internal: C7 local admin user (Argon2id hash, never plaintext)
CREATE TABLE platform_users (
    username      TEXT PRIMARY KEY,
    password_hash TEXT NOT NULL,
    role          TEXT NOT NULL DEFAULT 'OWNER',
    created_at    TEXT NOT NULL,
    updated_at    TEXT NOT NULL
);

-- Internal: C7 browser sessions (HttpOnly cookie + CSRF token)
CREATE TABLE user_sessions (
    session_id   TEXT PRIMARY KEY,
    username     TEXT NOT NULL REFERENCES platform_users(username),
    csrf_token   TEXT NOT NULL,
    kind         TEXT NOT NULL CHECK(kind IN ('user','service')),
    agent_id     TEXT REFERENCES agents(agent_id),
    created_at   TEXT NOT NULL,
    last_seen_at TEXT NOT NULL,
    expires_at   TEXT NOT NULL,
    revoked_at   TEXT
);
CREATE INDEX idx_user_sessions_username ON user_sessions(username);

-- Internal: C7/C8.6 local service identity for MCP/CLI agents (token hash only)
CREATE TABLE service_credentials (
    agent_id   TEXT PRIMARY KEY REFERENCES agents(agent_id),
    token_hash TEXT NOT NULL UNIQUE,
    created_at TEXT NOT NULL
);

